typeql:
match
$s isa stream, has name "itsbigchase";
$u isa user;
moderation (moderated_channel: $s, moderating_user: $u);
reduce $count = count($u);

match
$s isa stream, has total_view_count $tvc;
$tvc > 500000;
game_play (streaming_channel: $s, played_game: $g);
$g has name $gn;
select $gn;
distinct;
fetch {
  "game_name": $gn
};

match
$s isa stream;
moderation (moderated_channel: $s, moderating_user: $u1);
vip_status (channel_with_vips: $s, vip_user: $u2);
fetch {
  "name": $s.name,
  "stream_id": $s.stream_id,
  "description": $s.description,
  "url": $s.url,
  "followers": $s.followers,
  "total_view_count": $s.total_view_count
};

match
$t isa team, has created_at $ca;
$ca >= 2020-01-01T00:00:00;
$ca < 2021-01-01T00:00:00;
fetch {
  "name": $t.name
};

match
$s isa stream, has followers $f;
$f > 10000;
language_usage (channel: $s, used_language: $l);
$l has name $n;
select $n;
distinct;
sort $n;
limit 3;
fetch { "name": $n };

match
$u isa user, has name $userName;
$s isa stream;
chat_activity (chatting_user: $u, channel_with_chatters: $s);
reduce $streamCount = count($s) groupby $u, $userName;
match
$streamCount > 5;
fetch {
  "userName": $userName,
  "streamCount": $streamCount
};

match
$s isa stream, has stream_id $id, has name $n, has created_at $ca, has followers $f;
$ca >= 2015-01-01T00:00:00Z;
$ca <= 2020-12-31T23:59:59Z;
$f > 100000;
fetch {
  "id": $id,
  "name": $n,
  "createdAt": $ca,
  "followers": $f
};

match
$s isa stream;
$u isa user;
moderation (moderated_channel: $s, moderating_user: $u);
reduce $mod_count = count($u) groupby $s;
match $mod_count > 3;
fetch {
  "streamName": $s.name,
  "followerCount": $s.followers,
  "viewCount": $s.total_view_count
};

match
$s isa stream;
$g isa game, has name "Rust";
$l isa language, has name "en";
game_play (streaming_channel: $s, played_game: $g);
language_usage (channel: $s, used_language: $l);
fetch {
  "stream_name": $s.name,
  "follower_count": $s.followers
};

match
$s isa stream, has followers $f;
reduce $max_f = max($f);
match
$s2 isa stream, has followers $f2;
$f2 == $max_f;
vip_status (channel_with_vips: $s2, vip_user: $u);
fetch { "name": $u.name };

match
$s isa stream;
$u isa user;
moderation (moderated_channel: $s, moderating_user: $u);
reduce $moderatorCount = count($u) groupby $s;
match $moderatorCount > 1;
fetch { "streamName": $s.name, "moderatorCount": $moderatorCount };

match
$u1 isa user;
moderation (moderating_user: $u1, moderated_user: $u2);
$u2 isa user;
select $u1;
distinct;
fetch {
  "moderator_name": $u1.name
};

match
$s isa stream;
not { team_membership (member_stream: $s); };
fetch {
  "streamName": $s.name,
  "streamUrl": $s.url
};

match
$u isa user, has name "9linda";
$s isa stream;
chat_activity (chatting_user: $u, channel_with_chatters: $s);
fetch {
  "description": $s.description
};

match
$s isa stream, has total_view_count $tvc;
sort $tvc desc;
limit 3;
fetch {
  "url": $s.url
};

match
$s isa stream, has stream_id $sid, has name $sn, has created_at $ca;
$t isa team, has name $tn;
team_membership (member_stream: $s, organization: $t);
$ca >= 2018-01-01T00:00:00;
fetch {
  "streamId": $sid,
  "streamName": $sn,
  "creationDate": $ca,
  "teamName": $tn
};

match
$s isa stream;
$t isa team, has name "ESO Stream Team";
team_membership (member_stream: $s, organization: $t);
fetch {
  "stream_name": $s.name,
  "stream_url": $s.url
};

match
  $s isa stream;
  $t isa team, has name $tn;
  $g isa game, has name $gn;
  team_membership (member_stream: $s, organization: $t);
  game_play (streaming_channel: $s, played_game: $g);
  $tn like ".*E.*";
  $gn like ".*E.*";
limit 5;
fetch {
  "stream_name": $s.name,
  "team_name": $tn,
  "game_name": $gn
};

match
$s isa stream, has total_view_count $tvc;
$l isa language, has name "en";
language_usage (channel: $s, used_language: $l);
$tvc > 1000000;
fetch {
  "stream_name": $s.name,
  "stream_url": $s.url,
  "total_views": $tvc
};

match
$s isa stream, has total_view_count $v;
$v > 1000000;
language_usage (channel: $s, used_language: $l);
$l isa language, has name $n;
select $n;
distinct;
reduce $count = count;

match
$u isa user;
chat_activity (chatting_user: $u, channel_with_chatters: $s);
game_play (streaming_channel: $s, played_game: $g);
select $u, $g;
distinct;
reduce $gameCount = count groupby $u;
sort $gameCount desc;
limit 3;
fetch { "userName": $u.name, "gameCount": $gameCount };

match
$s isa stream, has name $sn, has created_at $ca;
$u isa user, has name $un;
moderation (moderated_channel: $s, moderating_user: $u);
$sn == $un;
sort $ca;
limit 5;
fetch {
  "s": { $s.* }
};

match
$s isa stream;
language_usage (channel: $s, used_language: $l);
reduce $lang_count = count($l) groupby $s;
sort $lang_count desc;
limit 1;
match
vip_status (channel_with_vips: $s, vip_user: $u);
$u has name $n;
limit 3;
fetch { "name": $n };

match
$s isa stream;
moderation (moderated_channel: $s, moderating_user: $u);
reduce $mod_count = count($u) groupby $s;
sort $mod_count desc;
limit 3;
match
game_play (streaming_channel: $s, played_game: $g);
$g has name $gn;
limit 3;
fetch { "gameName": $gn };

match
$s isa stream, has name $name, has followers $f;
$f >= 200000;
$f <= 500000;
sort $f desc;
limit 5;
fetch {
  "name": $name,
  "followers": $f
};

match
$t isa team, has created_at $ca;
$ca < 2015-01-01T00:00:00;
fetch {
  "name": $t.name
};

match
$u isa user;
$s isa stream;
chat_activity (chatting_user: $u, chatting_channel: $s);
vip_status (vip_user: $u, vip_channel: $s);
limit 5;
fetch { "userName": $u.name };

match
$u isa user, has name $name;
$s isa stream, has description $desc, has created_at $ca;
moderation (moderating_user: $u, moderated_channel: $s);
$desc like ".*professional.*";
sort $ca;
limit 5;
fetch { "name": $name };

match
$s isa stream, has name $sn, has created_at $ca;
$u isa user, has name $un;
moderation (moderated_channel: $s, moderating_user: $u);
$sn == $un;
sort $ca;
limit 5;
fetch {
  "name": $s.name,
  "created_at": $s.created_at,
  "stream_id": $s.stream_id,
  "description": $s.description,
  "url": $s.url,
  "followers": $s.followers,
  "total_view_count": $s.total_view_count
};

match
$s isa stream, has total_view_count $tvc;
$tvc > 10000000;
fetch {
  "name": $s.name,
  "total_view_count": $tvc
};

match
$s isa stream, has name $name, has followers $f;
sort $f desc;
limit 5;
fetch {
  "name": $name,
  "followers": $f
};

match
$s isa stream, has followers $f;
$f > 100000;
game_play (streaming_channel: $s, played_game: $g);
$g isa game;
select $g;
distinct;
fetch {
  "game_name": $g.name
};

match
$u isa user;
$s isa stream, has total_view_count $tvc;
$tvc > 500000;
moderation (moderating_user: $u, moderated_channel: $s);
fetch {
  "name": $u.name
};

match
$s isa stream;
$g isa game, has name "Rust";
game_play (streaming_channel: $s, played_game: $g);
fetch {
  "description": $s.description
};

match
$s isa stream, has name $sn, has stream_id $sid, has url $surl, has created_at $ca;
$u isa user, has name $un;
$un like "G.*";
moderation (moderated_channel: $s, moderating_user: $u);
sort $ca;
limit 3;
fetch {
  "name": $sn,
  "id": $sid,
  "url": $surl
};

match
$s isa stream;
vip_status (channel_with_vips: $s, vip_user: $u);
reduce $vip_count = count($u) groupby $s;
match
$vip_count > 5;
game_play (streaming_channel: $s, played_game: $g);
$g has name $game;
select $game;
distinct;
fetch { "game": $game };

match
$s isa stream, has followers $f;
language_usage (channel: $s, used_language: $l);
$l isa language;
sort $f desc;
limit 3;
select $l;
distinct;
fetch {
  "language": $l.name
};

match
$u isa user, has name "creightonolsen";
$s isa stream, has total_view_count $tvc;
chat_activity (chatting_user: $u, channel_with_chatters: $s);
$tvc > 100000;
fetch {
  "stream_name": $s.name,
  "stream_url": $s.url,
  "view_count": $tvc
};

match
$u isa user, has name "9linda";
vip_status (vip_user: $u, vip_channel: $s);
$s isa stream;
fetch {
  "stream_id": $s.stream_id,
  "name": $s.name,
  "description": $s.description,
  "url": $s.url,
  "created_at": $s.created_at,
  "followers": $s.followers,
  "total_view_count": $s.total_view_count
};

match
$s isa stream, has followers $f;
sort $f desc;
limit 5;
fetch {
  "name": $s.name
};

match
  $s isa stream, has total_view_count $v;
  $v > 1000000;
  game_play (streaming_channel: $s, played_game: $g);
  $g has name $name;
select $name;
distinct;
fetch {
  "game_name": $name
};

match
$s isa stream;
$l isa language, has name "en";
language_usage (channel: $s, used_language: $l);
limit 3;
fetch {
  "name": $s.name
};

match
$s isa stream;
$u isa user;
moderation (moderated_channel: $s, moderating_user: $u);
fetch {
  "stream_name": $s.name,
  "moderator_name": $u.name
};

match
$t isa team, has created_at $ca;
sort $ca desc;
limit 3;
fetch {
  "name": $t.name
};

match
$g isa game, has name "Rust";
$s isa stream;
game_play (streaming_channel: $s, played_game: $g);
reduce $numberOfStreams = count($s);

match
$s isa stream, has total_view_count $tvc;
sort $tvc desc;
limit 3;
fetch {
  "url": $s.url
};

match
$u isa user, has name $n;
$s isa stream;
moderation (moderating_user: $u, moderated_channel: $s);
reduce $streamCount = count($s) groupby $u, $n;
match $streamCount > 1;
sort $streamCount desc;
fetch { "moderatorName": $n, "streamCount": $streamCount };

match
$s isa stream, has followers $f;
$f > 5000000;
fetch {
  "stream_name": $s.name,
  "follower_count": $f
};

match
$s isa stream;
$g isa game, has name "Grand Theft Auto V";
$l isa language, has name "en";
game_play (streaming_channel: $s, played_game: $g);
language_usage (channel: $s, used_language: $l);
fetch {
  "name": $s.name
};

match
  $s isa stream, has name "itsbigchase";
  $u isa user, has name $vip_name;
  vip_status (channel_with_vips: $s, vip_user: $u);
fetch {
  "vip_users": $vip_name
};

match
$t isa team, has name "ESO Stream Team";
team_membership (member_stream: $s, organization: $t);
reduce $count = count($s);

match
$s isa stream, has created_at $ca;
$g isa game;
game_play (streaming_channel: $s, played_game: $g);
sort $ca asc;
limit 10;
fetch {
  "game_name": $g.name,
  "stream_created_at": $ca
};

match
$s isa stream, has created_at $ca;
sort $ca desc;
limit 5;
fetch {
  "name": $s.name,
  "created_at": $ca
};

match
$s isa stream, has description $d;
$d like ".*enjoy.*";
limit 3;
fetch {
  "name": $s.name,
  "description": $d
};

match
$s isa stream;
$rel isa vip_status (channel_with_vips: $s, vip_user: $u);
reduce $vip_count = count($rel) groupby $s;
match
$vip_count > 10;
fetch {
  "streamName": $s.name,
  "vipCount": $vip_count
};

match
$u isa user, has name "itsbigchase";
moderation (moderating_user: $u, moderated_channel: $s);
$s has total_view_count $v;
reduce $total = sum($v);

match
$u isa user, has name "itsbigchase";
moderation (moderating_user: $u, moderated_channel: $s);
$s isa stream;
fetch {
