chat_activity (chatting_user: $u, channel_with_chatters: $s);
$s isa stream;
fetch {
  "stream_name": $s.name,
  "stream_url": $s.url,
  "stream_description": $s.description
};

match
$u isa user;
$s isa stream;
$g isa game, has name "Rust";
moderation (moderating_user: $u, moderated_channel: $s);
game_play (streaming_channel: $s, played_game: $g);
fetch {
  "ModeratorName": $u.name
};

match
$t isa team;
$s isa stream;
team_membership (member_stream: $s, organization: $t);
reduce $stream_count = count($s) groupby $t;
sort $stream_count desc;
fetch { "team_name": $t.name, "stream_count": $stream_count };

match
$s isa stream, has followers $f;
sort $f desc;
limit 1;
fetch {
  "name": $s.name,
  "created_at": $s.created_at,
  "stream_id": $s.stream_id,
  "description": $s.description,
  "url": $s.url,
  "followers": $s.followers,
  "total_view_count": $s.total_view_count
};

match
$team isa team, has name "ESO Stream Team";
team_membership (member_stream: $stream, organization: $team);
game_play (streaming_channel: $stream, played_game: $game);
$game has name $game_name;
select $game_name;
distinct;
fetch { "game_name": $game_name };

match
$s isa stream, has followers $f;
$f > 500000;
$l isa language;
language_usage (channel: $s, used_language: $l);
reduce $count = count($s) groupby $l;
sort $count desc;
limit 1;
fetch { "language": $l.name, "stream_count": $count };

match
$s isa stream, has stream_id $sid, has name $n, has created_at $ca;
$ca < 2010-01-01T00:00:00;
fetch {
  "stream_id": $sid,
  "name": $n,
  "created_at": $ca
};

match
$s isa stream;
$u isa user;
vip_status (vip_user: $u, vip_channel: $s);
moderation (moderating_user: $u, moderated_channel: $s);
fetch {
  "streamName": $s.name,
  "streamUrl": $s.url,
  "userName": $u.name
};

match
$u isa user, has name $n;
$s isa stream;
moderation (moderating_user: $u, moderated_channel: $s);
reduce $count = count($s) groupby $u, $n;
sort $count desc;
limit 5;
fetch { "user_name": $n, "moderated_streams": $count };

match
$s isa stream, has created_at $ca;
sort $ca asc;
limit 1;
fetch {
  "description": $s.description
};

match
$s isa stream;
$g isa game;
$t isa team, has created_at $ca;
$ca > 2017-01-01T00:00:00Z;
game_play (streaming_channel: $s, played_game: $g);
team_membership (member_stream: $s, organization: $t);
select $g;
distinct;
fetch {
  "game_name": $g.name
};

match
$s isa stream;
$l isa language, has name $language;
language_usage (channel: $s, used_language: $l);
reduce $stream_count = count($s) groupby $language;
sort $stream_count desc;

match
$s isa stream, has name $name;
$u isa user;
chat_activity (channel_with_chatters: $s, chatting_user: $u);
reduce $chatter_count = count($u) groupby $s, $name;
sort $chatter_count desc;
limit 3;
fetch { "streamName": $name, "chatterCount": $chatter_count };

match
$u isa user;
$s isa stream, has total_view_count $tvc;
$tvc > 5000000;
vip_status (vip_user: $u, vip_channel: $s);
fetch {
  "name": $u.name
};

match
$u isa user, has name "itsbigchase";
$s isa stream, has stream_id $sid, has name $sn, has description $desc, has url $surl, has followers $sf, has total_view_count $stvc, has created_at $sca;
moderation (moderating_user: $u, moderated_channel: $s);
fetch {
  "s.id": $sid,
  "s.name": $sn,
  "s.description": $desc,
  "s.url": $surl,
  "s.followers": $sf,
  "s.total_view_count": $stvc,
