match
$s isa stream, has followers $f;
$f >= 10000;
$f <= 50000;
sort $f desc;
limit 5;
fetch {
  "name": $s.name,
  "followers": $f
};

with fun max_followers() -> integer:
  match $s isa stream, has followers $f;
  return max($f);
match
$s isa stream, has followers $f;
let $max = max_followers();
$f == $max;
vip_status (vip_channel: $s, vip_user: $u);
$u isa user;
limit 3;
fetch {
  "name": $u.name
};

match
$s isa stream, has created_at $ca;
vip_status (vip_channel: $s, channel_with_vips: $vip_stream);
$vip_stream isa stream;
not { $u isa user; vip_status ($s, vip_user: $u); };
sort $ca;
limit 3;
fetch {
  "name": $s.name,
  "url": $s.url,
  "created_at": $ca
};

match
$g isa game, has name "Rust";
$s isa stream;
$u isa user, has name $n;
game_play (streaming_channel: $s, played_game: $g);
chat_activity (chatting_user: $u, chatting_channel: $s);
limit 5;
fetch { "name": $n };

match
$s isa stream;
$t isa team, has created_at $ca;
team_membership (member_stream: $s, organization: $t);
$ca < 2015-01-01T00:00:00;
sort $ca asc;
limit 3;
fetch {
  "stream_name": $s.name,
  "stream_url": $s.url,
  "team_name": $t.name,
  "team_createdAt": $ca
};

match
$s isa stream, has name $sn, has url $u, has total_view_count $tvc;
$g isa game, has name "VALORANT";
game_play (streaming_channel: $s, played_game: $g);
$tvc > 1000000;
sort $tvc desc;
limit 5;
fetch {
  "name": $sn,
  "url": $u,
  "total_view_count": $tvc
};

match
$u isa user, has name $n;
$s isa stream, has created_at $ca;
moderation (moderating_user: $u, moderated_channel: $s);
$ca < 2015-01-01T00:00:00;
sort $ca asc;
limit 3;
fetch {
  "moderator_name": $n,
  "moderator_since": $ca
};

match
$s isa stream;
$g isa game;
game_play (streaming_channel: $s, played_game: $g);
select $s, $g;
distinct;
reduce $game_count = count($g) groupby $s;
match
$game_count > 1;
$s has created_at $ca;
sort $ca asc;
limit 5;
fetch {
  "streamName": $s.name,
  "streamId": $s.stream_id
};

match
$s isa stream, has followers $f;
$f > 1000000;
$g isa game, has name "Rust";
game_play (streaming_channel: $s, played_game: $g);
team_membership (member_stream: $s, organization: $t);
$s has created_at $ca;
sort $ca;
limit 3;
fetch {
  "name": $t.name
};

match
$s isa stream, has description $d;
$d like ".*professional.*";
limit 3;
fetch {
  "name": $s.name,
  "description": $d
};

match
$g isa game, has name "Dota 2";
$s isa stream;
game_play (streaming_channel: $s, played_game: $g);
$u isa user, has name $n;
chat_activity (chatting_user: $u, channel_with_chatters: $s);
limit 5;
fetch { "name": $n };

match
$s isa stream, has total_view_count $tvc;
$tvc > 10000000;
$l isa language;
language_usage (channel: $s, used_language: $l);
reduce $count = count groupby $l;
sort $count desc;
limit 3;
fetch {
  "language": $l.name,
  "count": $count
};

match
$s isa stream;
$g isa game;
$l isa language, has name "ja";
game_play (streaming_channel: $s, played_game: $g);
language_usage (channel: $s, used_language: $l);
$g has name $gn;
limit 3;
fetch { "name": $gn };

match
$s isa stream;
moderation (moderated_channel: $s, moderating_user: $u);
reduce $mod_count = count($u) groupby $s;
sort $mod_count desc;
limit 1;
match
vip_status (vip_channel: $s, vip_user: $vip);
$vip has name $vip_name;
sort $vip_name asc;
limit 3;
fetch {
  "name": $vip_name
};

match
$s isa stream, has followers $f, has created_at $ca;
$f == 100000;
sort $ca;
limit 5;
fetch {
  "name": $s.name,
  "stream_id": $s.stream_id,
  "description": $s.description,
  "url": $s.url,
  "followers": $f,
  "total_view_count": $s.total_view_count,
  "created_at": $ca
};

match
  $s isa stream;
  $t isa team;
  team_membership (member_stream: $s, organization: $t);
  $s has created_at $s_created;
  $t has created_at $t_created;
  $s_created >= $t_created;
sort $s_created asc;
limit 3;
fetch {
  "stream_name": $s.name,
  "stream_url": $s.url,
  "stream_created_at": $s_created
};

match
$s isa stream, has created_at $ca;
game_play (streaming_channel: $s, played_game: $g);
reduce $game_count = count($g) groupby $s, $ca;
match
$game_count == 1;
$s has name $sn;
game_play (streaming_channel: $s, played_game: $g2);
$g2 has name $gn;
sort $ca asc;
limit 3;
fetch {
  "stream_name": $sn,
  "creation_date": $ca,
  "game_name": $gn
