game_play (streaming_channel: $s, played_game: $g);
team_membership (member_stream: $s, organization: $t);
reduce $total_views = sum($v) groupby $g;
sort $total_views desc;
limit 3;
fetch { "game": $g.name, "total_views": $total_views };

match
$s isa stream;
$u isa user;
moderation (moderated_channel: $s, moderating_user: $u);
reduce $count = count($u) groupby $s;
sort $count desc;
limit 3;
fetch { "name": $s.name, "moderator_count": $count };

match
$s isa stream;
$l isa language;
language_usage (channel: $s, used_language: $l);
reduce $count = count($s) groupby $l;
sort $count asc;
limit 3;
fetch {
  "language": $l.name,
  "streamCount": $count
};

match
$u isa user;
$rel isa moderation (moderating_user: $u);
reduce $count = count($rel) groupby $u;
sort $count desc;
limit 3;
fetch { "user": $u.name, "moderation_count": $count };

match
$s isa stream;
$rel isa vip_status (channel_with_vips: $s, vip_user: $u);
reduce $vip_count = count($u) groupby $s;
sort $vip_count desc;
limit 3;
fetch { "name": $s.name, "vip_count": $vip_count };

match
$s isa stream;
